const d = new Date(2026, 8, 1); // September 1, 2026
const dayOfWeek = d.getDay(); // 0=Sun, 1=Mon
const daysUntilMon = dayOfWeek === 0 ? 1 : (dayOfWeek === 1 ? 0 : 8 - dayOfWeek);
const laborDay = new Date(2026, 8, 1 + daysUntilMon);
console.log('Labor Day 2026:', laborDay.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }));
"
